package server_test

import (
	"fmt"
	"path/filepath"
	"testing"
	"time"

	"github.com/stretchr/testify/require"

	"github.com/kopia/kopia/internal/apiclient"
	"github.com/kopia/kopia/internal/repotesting"
	"github.com/kopia/kopia/internal/serverapi"
	"github.com/kopia/kopia/internal/servertesting"
	"github.com/kopia/kopia/internal/testutil"
	"github.com/kopia/kopia/repo/compression"
	"github.com/kopia/kopia/snapshot"
	"github.com/kopia/kopia/snapshot/policy"
)

func TestPolicies(t *testing.T) {
	ctx, env := repotesting.NewEnvironment(t, repotesting.FormatNotImportant)
	srvInfo := servertesting.StartServer(t, env, false)

	cli, err := apiclient.NewKopiaAPIClient(apiclient.Options{
		BaseURL:                             srvInfo.BaseURL,
		TrustedServerCertificateFingerprint: srvInfo.TrustedServerCertificateFingerprint,
		Username:                            servertesting.TestUIUsername,
		Password:                            <REDACTED>
	})

	require.NoError(t, err)
	require.NoError(t, cli.FetchCSRFTokenForTesting(ctx))

	dir0 := testutil.TempDirectory(t)
	si0 := env.LocalPathSourceInfo(dir0)

	dir1 := testutil.TempDirectory(t)
	si1 := env.LocalPathSourceInfo(dir1)

	dir2 := filepath.Join(dir1, "subdir1")
	si2 := env.LocalPathSourceInfo(dir2)

	dir3 := filepath.Join(dir2, "subdir2")
	si3 := env.LocalPathSourceInfo(dir3)

	dir4 := filepath.Join(dir3, "subdir3")
	si4 := env.LocalPathSourceInfo(dir4)

	mustSetPolicy(t, cli, si1, &policy.Policy{
		CompressionPolicy: policy.CompressionPolicy{
			CompressorName: "some-compressor",
		},
	})

	mustSetPolicy(t, cli, si2, &policy.Policy{
		CompressionPolicy: policy.CompressionPolicy{
			NeverCompress: []string{"a", "b"},
		},
		SchedulingPolicy: policy.SchedulingPolicy{
			IntervalSeconds: 60,
		},
	})

	mustSetPolicy(t, cli, si3, &policy.Policy{
		CompressionPolicy: policy.CompressionPolicy{
			CompressorName: "some-compressor3",
		},
	})

	cases := []struct {
		si                              snapshot.SourceInfo
		updates                         *policy.Policy
		wantCompressorName              compression.Name
		wantCompressorNameSource        snapshot.SourceInfo
		wantNeverCompress               []string
		wantNeverCompressSource         snapshot.SourceInfo
		wantUpcomingSnapshotTimesLength int
		wantSchedulingError             string
	}{
		{
			si:                       si0,
			wantCompressorName:       compression.Name("none"),
			wantNeverCompress:        nil,
			wantCompressorNameSource: policy.GlobalPolicySourceInfo,
			wantNeverCompressSource:  policy.GlobalPolicySourceInfo,
		},
		{
			si:                       si1,
			wantCompressorName:       compression.Name("some-compressor"),
			wantNeverCompress:        nil,
			wantCompressorNameSource: si1,
			wantNeverCompressSource:  policy.GlobalPolicySourceInfo,
		},
		{
			si:                       si1,
			wantCompressorName:       compression.Name("some-compressor-updated"),
			wantNeverCompress:        nil,
			wantCompressorNameSource: si1,
			wantNeverCompressSource:  policy.GlobalPolicySourceInfo,
			updates: &policy.Policy{
				CompressionPolicy: policy.CompressionPolicy{
					CompressorName: "some-compressor-updated",
				},
			},
		},
		{
			si:                              si2,
			wantCompressorName:              compression.Name("some-compressor"), // inherited
			wantNeverCompress:               []string{"a", "b"},
			wantCompressorNameSource:        si1,
			wantNeverCompressSource:         si2,
			wantUpcomingSnapshotTimesLength: 3,
		},
		{
			si:                              si3,
			wantCompressorName:              compression.Name("some-compressor3"),
			wantNeverCompress:               []string{"a", "b"},
			wantCompressorNameSource:        si3,
			wantNeverCompressSource:         si2,
			wantUpcomingSnapshotTimesLength: 3,
		},
		{
			si:                              si4,
			wantCompressorName:              compression.Name("some-compressor3"),
			wantNeverCompress:               []string{"a", "b"},
			wantCompressorNameSource:        si3,
			wantNeverCompressSource:         si2,
			wantUpcomingSnapshotTimesLength: 3,
		},
		{
			si:                       si4,
			wantCompressorName:       compression.Name("some-compressor-updated"),
			wantNeverCompress:        []string{"a", "b"},
			wantCompressorNameSource: si4,
			wantNeverCompressSource:  si2,
			updates: &policy.Policy{
				CompressionPolicy: policy.CompressionPolicy{
					CompressorName: "some-compressor-updated",
				},
			},
			wantUpcomingSnapshotTimesLength: 3,
		},
		{
			si:                       si0,
			wantCompressorName:       compression.Name("none"),
			wantNeverCompress:        nil,
			wantCompressorNameSource: policy.GlobalPolicySourceInfo,
			wantNeverCompressSource:  policy.GlobalPolicySourceInfo,
			updates: &policy.Policy{
				SchedulingPolicy: policy.SchedulingPolicy{
					Cron: []string{"invalid"},
				},
			},
			wantSchedulingError: "invalid cron expression \"invalid\"",
		},
	}

	for i, tc := range cases {
		t.Run(fmt.Sprintf("case-%v", i), func(t *testing.T) {
			res, err2 := serverapi.ResolvePolicy(ctx, cli, tc.si, &serverapi.ResolvePolicyRequest{
				Updates:                  tc.updates,
				NumUpcomingSnapshotTimes: 3,
			})
			require.NoError(t, err2)
			require.Equal(t, tc.wantCompressorName, res.Effective.CompressionPolicy.CompressorName)
			require.Equal(t, tc.wantNeverCompress, res.Effective.CompressionPolicy.NeverCompress)
			require.Equal(t, tc.wantCompressorNameSource, res.Definition.CompressionPolicy.CompressorName)
			require.Equal(t, tc.wantNeverCompressSource, res.Definition.CompressionPolicy.NeverCompress)
			require.Len(t, res.UpcomingSnapshotTimes, tc.wantUpcomingSnapshotTimesLength)
			require.Equal(t, tc.wantSchedulingError, res.SchedulingError)

			for j, ust := range res.UpcomingSnapshotTimes {
				require.Equal(t, ust.Truncate(60*time.Second), ust)

				if j > 0 {
					require.Equal(t, 60*time.Second, ust.Sub(res.UpcomingSnapshotTimes[j-1]))
				}
			}
		})
	}
}

package server_test

import (
	"sync/atomic"
	"testing"

	"github.com/pkg/errors"
	"github.com/stretchr/testify/require"

	"github.com/kopia/kopia/internal/apiclient"
	"github.com/kopia/kopia/internal/repotesting"
	"github.com/kopia/kopia/internal/serverapi"
	"github.com/kopia/kopia/internal/servertesting"
	"github.com/kopia/kopia/notification/notifyprofile"
	"github.com/kopia/kopia/notification/sender"
	"github.com/kopia/kopia/notification/sender/testsender"
)

func TestNotificationProfile(t *testing.T) {
	ctx, env := repotesting.NewEnvironment(t, repotesting.FormatNotImportant)

	var (
		numMessagesSent atomic.Int32
		nextSendErr     error
	)

	ctx = testsender.CaptureMessagesWithHandler(ctx, func(msg *sender.Message) error {
		var returnErr error

		numMessagesSent.Add(1)

		returnErr, nextSendErr = nextSendErr, nil

		return returnErr
	})

	srvInfo := servertesting.StartServerContext(ctx, t, env, false)

	cli, err := apiclient.NewKopiaAPIClient(apiclient.Options{
		BaseURL:                             srvInfo.BaseURL,
		TrustedServerCertificateFingerprint: srvInfo.TrustedServerCertificateFingerprint,
		Username:                            servertesting.TestUIUsername,
		Password:                            <REDACTED>
	})

	require.NoError(t, err)

	require.NoError(t, cli.FetchCSRFTokenForTesting(ctx))

	var profiles []notifyprofile.Config

	require.NoError(t, cli.Get(ctx, "notificationProfiles", nil, &profiles))
	require.Empty(t, profiles)

	// test new profile
	require.EqualValues(t, 0, numMessagesSent.Load())

	require.ErrorContains(t, cli.Post(ctx, "testNotificationProfile", &notifyprofile.Config{
		ProfileName: "profile1",
		MethodConfig: sender.MethodConfig{
			Type: "invalid-type",
			Config: testsender.Options{
				Format: "txt",
			},
		},
		MinSeverity: 3,
	}, &serverapi.Empty{}), "malformed request body")

	require.ErrorContains(t, cli.Post(ctx, "testNotificationProfile", &notifyprofile.Config{
		ProfileName: "profile1",
		MethodConfig: sender.MethodConfig{
			Type: "testsender",
			Config: testsender.Options{
				Format:  "txt",
				Invalid: true,
			},
		},
		MinSeverity: 3,
	}, &serverapi.Empty{}), "unable to construct sender")

	// nothing was sent
	require.EqualValues(t, 0, numMessagesSent.Load())

	nextSendErr = errors.Errorf("test error")

	require.ErrorContains(t, cli.Post(ctx, "testNotificationProfile", &notifyprofile.Config{
		ProfileName: "profile1",
		MethodConfig: sender.MethodConfig{
			Type: "testsender",
			Config: testsender.Options{
				Format: "txt",
			},
		},
		MinSeverity: 3,
	}, &serverapi.Empty{}), "test error")

	// expect one message to be sent
	require.EqualValues(t, 1, numMessagesSent.Load())

	require.NoError(t, cli.Post(ctx, "testNotificationProfile", &notifyprofile.Config{
		ProfileName: "profile1",
		MethodConfig: sender.MethodConfig{
			Type: "testsender",
			Config: testsender.Options{
				Format: "txt",
			},
		},
		MinSeverity: 3,
	}, &serverapi.Empty{}))
	require.EqualValues(t, 2, numMessagesSent.Load())

	// define new profile
	require.NoError(t, cli.Post(ctx, "notificationProfiles", &notifyprofile.Config{
		ProfileName: "profile1",
		MethodConfig: sender.MethodConfig{
			Type: "testsender",
			Config: testsender.Options{
				Format: "txt",
			},
		},
		MinSeverity: 3,
	}, &serverapi.Empty{}))

	// define invalid profile
	require.ErrorContains(t, cli.Post(ctx, "notificationProfiles", &notifyprofile.Config{
		ProfileName: "profile2",
		MethodConfig: sender.MethodConfig{
			Type: "no-such-type",
			Config: testsender.Options{
				Format: "txt",
			},
		},
		MinSeverity: 3,
	}, &serverapi.Empty{}), "malformed request body")

	var cfg notifyprofile.Config

	// get profile and verify
	require.NoError(t, cli.Get(ctx, "notificationProfiles/profile1", nil, &cfg))
	require.Equal(t, "profile1", cfg.ProfileName)
	require.Equal(t, sender.Method("testsender"), cfg.MethodConfig.Type)

	opt, ok := cfg.MethodConfig.Config.(map[string]any)
	require.True(t, ok)
	require.Equal(t, "txt", opt["format"])

	// get non-existent profile
	require.ErrorContains(t, cli.Get(ctx, "notificationProfiles/profile2", nil, &cfg), "profile not found")

	// list profiles
	require.NoError(t, cli.Get(ctx, "notificationProfiles", nil, &profiles))
	require.Len(t, profiles, 1)
	require.Equal(t, "profile1", profiles[0].ProfileName)

	// delete the profile, ensure idempotent
	require.NoError(t, cli.Delete(ctx, "notificationProfiles/profile1", nil, nil, &serverapi.Empty{}))
	require.NoError(t, cli.Delete(ctx, "notificationProfiles/profile1", nil, nil, &serverapi.Empty{}))

	// verify it's gone
	require.NoError(t, cli.Get(ctx, "notificationProfiles", nil, &profiles))
	require.Empty(t, profiles)
}

package server_test

import (
	"net/http"
	"strings"
	"testing"

	"github.com/stretchr/testify/require"

	"github.com/kopia/kopia/internal/apiclient"
	"github.com/kopia/kopia/internal/repotesting"
	"github.com/kopia/kopia/internal/serverapi"
	"github.com/kopia/kopia/internal/servertesting"
	"github.com/kopia/kopia/internal/testutil"
)

func TestPathsAPI(t *testing.T) {
	ctx, env := repotesting.NewEnvironment(t, repotesting.FormatNotImportant)
	srvInfo := servertesting.StartServer(t, env, false)

	cli, err := apiclient.NewKopiaAPIClient(apiclient.Options{
		BaseURL:                             srvInfo.BaseURL,
		TrustedServerCertificateFingerprint: srvInfo.TrustedServerCertificateFingerprint,
		Username:                            servertesting.TestUIUsername,
		Password:                            <REDACTED>
	})

	require.NoError(t, err)
	require.NoError(t, cli.FetchCSRFTokenForTesting(ctx))

	dir0 := testutil.TempDirectory(t)

	req := &serverapi.ResolvePathRequest{
		Path: dir0,
	}
	resp := &serverapi.ResolvePathResponse{}
	require.NoError(t, cli.Post(ctx, "paths/resolve", req, resp))

	require.Equal(t, env.LocalPathSourceInfo(dir0), resp.SourceInfo)
}

func TestPathsAPI_RequestBodyTooLarge(t *testing.T) {
	ctx, env := repotesting.NewEnvironment(t, repotesting.FormatNotImportant)
	srvInfo := servertesting.StartServer(t, env, false)

	cli, err := apiclient.NewKopiaAPIClient(apiclient.Options{
		BaseURL:                             srvInfo.BaseURL,
		TrustedServerCertificateFingerprint: srvInfo.TrustedServerCertificateFingerprint,
		Username:                            servertesting.TestUIUsername,
		Password:                            <REDACTED>
	})

	require.NoError(t, err)
	require.NoError(t, cli.FetchCSRFTokenForTesting(ctx))

	// the request body limit is 100_000 bytes, so a path much longer than that
	// must be rejected before it reaches the handler.
	req := &serverapi.ResolvePathRequest{
		Path: strings.Repeat("a", 105_000),
	}
	resp := &serverapi.ResolvePathResponse{}

	err = cli.Post(ctx, "paths/resolve", req, resp)
	require.Error(t, err)

	var hsr apiclient.HTTPStatusError

	require.ErrorAs(t, err, &hsr)
	require.Equal(t, http.StatusRequestEntityTooLarge, hsr.HTTPStatusCode)
}

package server

import (
	"context"
	"encoding/json"
	"net/url"
	"time"

	"github.com/pkg/errors"

	"github.com/kopia/kopia/internal/clock"
	"github.com/kopia/kopia/internal/serverapi"
	"github.com/kopia/kopia/repo"
	"github.com/kopia/kopia/snapshot"
	"github.com/kopia/kopia/snapshot/policy"
)

func handlePolicyList(ctx context.Context, rc requestContext) (any, *apiError) {
	policies, err := policy.ListPolicies(ctx, rc.rep)
	if err != nil {
		return nil, internalServerError(err)
	}

	resp := &serverapi.PoliciesResponse{
		Policies: []*serverapi.PolicyListEntry{},
	}

	for _, pol := range policies {
		target := pol.Target()
		if !sourceMatchesURLFilter(target, rc.req.URL.Query()) {
			continue
		}

		resp.Policies = append(resp.Policies, &serverapi.PolicyListEntry{
			ID:     pol.ID(),
			Target: target,
			Policy: pol,
		})
	}

	return resp, nil
}

func getSnapshotSourceFromURL(u *url.URL) snapshot.SourceInfo {
	host := u.Query().Get("host")
	path := u.Query().Get("path")
	username := u.Query().Get("userName")

	return snapshot.SourceInfo{
		Host:     host,
		Path:     path,
		UserName: username,
	}
}

func handlePolicyGet(ctx context.Context, rc requestContext) (any, *apiError) {
	pol, err := policy.GetDefinedPolicy(ctx, rc.rep, getSnapshotSourceFromURL(rc.req.URL))
	if errors.Is(err, policy.ErrPolicyNotFound) {
		return nil, requestError(serverapi.ErrorNotFound, "policy not found")
	}

	return pol, nil
}

func handlePolicyResolve(ctx context.Context, rc requestContext) (any, *apiError) {
	var req serverapi.ResolvePolicyRequest

	if err := json.Unmarshal(rc.body, &req); err != nil {
		return nil, unableToDecodeRequest(err)
	}

	target := getSnapshotSourceFromURL(rc.req.URL)

	// build a list of parents
	policies, err := policy.GetPolicyHierarchy(ctx, rc.rep, target, nil)
	if err != nil {
		return nil, internalServerError(err)
	}

	resp := &serverapi.ResolvePolicyResponse{
		Defined: policies[0],
	}

	if req.Updates != nil {
		policies[0] = req.Updates
		policies[0].Labels = policy.LabelsForSource(target)
	}

	resp.Effective, resp.Definition = policy.MergePolicies(policies, target)
	resp.UpcomingSnapshotTimes = []time.Time{}

	if err := policy.ValidateSchedulingPolicy(policies[0].SchedulingPolicy); err != nil {
		resp.SchedulingError = err.Error()
	}

	now := clock.Now().Local()

	for range req.NumUpcomingSnapshotTimes {
		st, ok := resp.Effective.SchedulingPolicy.NextSnapshotTime(now, now)
		if !ok {
			break
		}

		resp.UpcomingSnapshotTimes = append(resp.UpcomingSnapshotTimes, st)
		now = st.Add(1 * time.Second)
	}

	return resp, nil
}

func handlePolicyDelete(ctx context.Context, rc requestContext) (any, *apiError) {
	if _, ok := rc.rep.(repo.RepositoryWriter); !ok {
		return nil, repositoryNotWritableError()
	}

	sourceInfo := getSnapshotSourceFromURL(rc.req.URL)

	if err := repo.WriteSession(ctx, rc.rep, repo.WriteSessionOptions{
		Purpose: "PolicyDelete",
	}, func(ctx context.Context, w repo.RepositoryWriter) error {
		return errors.Wrap(policy.RemovePolicy(ctx, w, sourceInfo), "unable to delete policy")
	}); err != nil {
		return nil, internalServerError(err)
	}

	rc.srv.Refresh()

	return &serverapi.Empty{}, nil
}

func handlePolicyPut(ctx context.Context, rc requestContext) (any, *apiError) {
	newPolicy := &policy.Policy{}
	if err := json.Unmarshal(rc.body, newPolicy); err != nil {
		return nil, requestError(serverapi.ErrorMalformedRequest, "malformed request body")
	}

	if _, ok := rc.rep.(repo.RepositoryWriter); !ok {
		return nil, repositoryNotWritableError()
	}

	sourceInfo := getSnapshotSourceFromURL(rc.req.URL)

	if err := repo.WriteSession(ctx, rc.rep, repo.WriteSessionOptions{
		Purpose: "PolicyPut",
	}, func(ctx context.Context, w repo.RepositoryWriter) error {
		return errors.Wrap(policy.SetPolicy(ctx, w, sourceInfo, newPolicy), "unable to set policy")
	}); err != nil {
		return nil, internalServerError(err)
	}

	rc.srv.Refresh()

	return &serverapi.Empty{}, nil
}

package server_test

import (
	"context"
	"math"
	"path/filepath"
	"testing"
	"time"

	"github.com/google/uuid"
	"github.com/stretchr/testify/require"

	"github.com/kopia/kopia/internal/apiclient"
	"github.com/kopia/kopia/internal/mockfs"
	"github.com/kopia/kopia/internal/repotesting"
	"github.com/kopia/kopia/internal/serverapi"
	"github.com/kopia/kopia/internal/servertesting"
	"github.com/kopia/kopia/internal/testutil"
	"github.com/kopia/kopia/internal/uitask"
	"github.com/kopia/kopia/repo"
	"github.com/kopia/kopia/repo/manifest"
	"github.com/kopia/kopia/snapshot"
	"github.com/kopia/kopia/snapshot/restore"
	"github.com/kopia/kopia/snapshot/upload"
)

func TestRestoreSnapshots(t *testing.T) {
	ctx, env := repotesting.NewEnvironment(t, repotesting.FormatNotImportant)

	si1 := env.LocalPathSourceInfo("/dummy/path")

	var id11 manifest.ID

	require.NoError(t, repo.WriteSession(ctx, env.Repository, repo.WriteSessionOptions{Purpose: "Test"}, func(ctx context.Context, w repo.RepositoryWriter) error {
		u := upload.NewUploader(w)

		dir1 := mockfs.NewDirectory()

		dir1.AddFile("file1", []byte{1, 2, 3}, 0o644)
		dir1.AddDir("dir1", 0o644).AddFile("file2", []byte{1, 2, 4}, 0o644)

		man11, err := u.Upload(ctx, dir1, nil, si1)
		require.NoError(t, err)
		id11, err = snapshot.SaveSnapshot(ctx, w, man11)
		require.NoError(t, err)

		return nil
	}))

	srvInfo := servertesting.StartServer(t, env, false)

	cli, err := apiclient.NewKopiaAPIClient(apiclient.Options{
		BaseURL:                             srvInfo.BaseURL,
		TrustedServerCertificateFingerprint: srvInfo.TrustedServerCertificateFingerprint,
		Username:                            servertesting.TestUIUsername,
		Password:                            <REDACTED>
	})

	require.NoError(t, err)
	require.NoError(t, cli.FetchCSRFTokenForTesting(ctx))

	t.Run("Filesystem", func(t *testing.T) {
		targetPath1 := testutil.TempDirectory(t)
		restoreTask1, err := serverapi.Restore(ctx, cli, &serverapi.RestoreRequest{
			Root: string(id11),
			Options: restore.Options{
				RestoreDirEntryAtDepth: math.MaxInt32,
			},
			Filesystem: &restore.FilesystemOutput{
				TargetPath:      targetPath1,
				SkipOwners:      true,
				SkipPermissions: true,
			},
		})

		require.NoError(t, err)
		waitForTask(t, cli, restoreTask1.TaskID, 30*time.Second)
		require.FileExists(t, filepath.Join(targetPath1, "file1"))
		require.FileExists(t, filepath.Join(targetPath1, "dir1", "file2"))
	})

	t.Run("FilesystemSubdir", func(t *testing.T) {
		targetPath1 := testutil.TempDirectory(t)
		restoreTask1, err := serverapi.Restore(ctx, cli, &serverapi.RestoreRequest{
			Root: string(id11) + "/dir1",
			Options: restore.Options{
				RestoreDirEntryAtDepth: math.MaxInt32,
			},
			Filesystem: &restore.FilesystemOutput{
				TargetPath:      targetPath1,
				SkipOwners:      true,
				SkipPermissions: true,
			},
		})

		require.NoError(t, err)
		require.Equal(t, uitask.StatusSuccess, waitForTask(t, cli, restoreTask1.TaskID, 30*time.Second).Status)

		require.FileExists(t, filepath.Join(targetPath1, "file2"))
	})

	t.Run("FilesystemFullShallowRestore", func(t *testing.T) {
		targetPath1 := testutil.TempDirectory(t)
		restoreTask1, err := serverapi.Restore(ctx, cli, &serverapi.RestoreRequest{
			Root:    string(id11),
			Options: restore.Options{},
			Filesystem: &restore.FilesystemOutput{
				TargetPath:      targetPath1,
				SkipOwners:      true,
				SkipPermissions: true,
			},
		})

		require.NoError(t, err)
		require.Equal(t, uitask.StatusSuccess, waitForTask(t, cli, restoreTask1.TaskID, 30*time.Second).Status)
		require.FileExists(t, filepath.Join(targetPath1, "file1.kopia-entry"))
		require.DirExists(t, filepath.Join(targetPath1, "dir1.kopia-entry"))
		require.FileExists(t, filepath.Join(targetPath1, "dir1.kopia-entry", ".kopia-entry"))
	})

	t.Run("FilesystemPartialShallowRestore", func(t *testing.T) {
		targetPath1 := testutil.TempDirectory(t)
		restoreTask1, err := serverapi.Restore(ctx, cli, &serverapi.RestoreRequest{
			Root: string(id11),
			Options: restore.Options{
				RestoreDirEntryAtDepth: 1,
			},
			Filesystem: &restore.FilesystemOutput{
				TargetPath:      targetPath1,
				SkipOwners:      true,
				SkipPermissions: true,
			},
		})

		require.NoError(t, err)
		require.Equal(t, uitask.StatusSuccess, waitForTask(t, cli, restoreTask1.TaskID, 30*time.Second).Status)
		require.FileExists(t, filepath.Join(targetPath1, "file1"))
		require.DirExists(t, filepath.Join(targetPath1, "dir1"))
		require.FileExists(t, filepath.Join(targetPath1, "dir1", "file2.kopia-entry"))
	})

	t.Run("ZipFile", func(t *testing.T) {
		outputZipFile := filepath.Join(testutil.TempDirectory(t), "test1.zip")
		restoreTask1, err := serverapi.Restore(ctx, cli, &serverapi.RestoreRequest{
			Root: string(id11),
			Options: restore.Options{
				RestoreDirEntryAtDepth: math.MaxInt32,
			},
			ZipFile: outputZipFile,
		})

		require.NoError(t, err)
		require.Equal(t, uitask.StatusSuccess, waitForTask(t, cli, restoreTask1.TaskID, 30*time.Second).Status)
		require.FileExists(t, outputZipFile)
	})

	t.Run("UncompressedZipFile", func(t *testing.T) {
		outputZipFile := filepath.Join(testutil.TempDirectory(t), "test1.zip")
		restoreTask1, err := serverapi.Restore(ctx, cli, &serverapi.RestoreRequest{
			Root: string(id11),
			Options: restore.Options{
				RestoreDirEntryAtDepth: math.MaxInt32,
			},
			ZipFile:         outputZipFile,
			UncompressedZip: true,
		})

		require.NoError(t, err)
		require.Equal(t, uitask.StatusSuccess, waitForTask(t, cli, restoreTask1.TaskID, 30*time.Second).Status)
		require.FileExists(t, outputZipFile)
	})

	t.Run("TarFile", func(t *testing.T) {
		outputTarFile := filepath.Join(testutil.TempDirectory(t), "test1.tar")
		restoreTask1, err := serverapi.Restore(ctx, cli, &serverapi.RestoreRequest{
			Root: string(id11),
			Options: restore.Options{
				RestoreDirEntryAtDepth: math.MaxInt32,
			},
			TarFile: outputTarFile,
		})

		require.NoError(t, err)
		require.Equal(t, uitask.StatusSuccess, waitForTask(t, cli, restoreTask1.TaskID, 30*time.Second).Status)
		require.FileExists(t, outputTarFile)
	})

	t.Run("InvalidRequest", func(t *testing.T) {
		requests := []*serverapi.RestoreRequest{
			{
				Root: string(id11),
				// no output
			},
			{
				// no root
				ZipFile: filepath.Join(testutil.TempDirectory(t), "test1.zip"),
			},
			{
				Root:    string(id11 + "bad"),
				ZipFile: filepath.Join(testutil.TempDirectory(t), "test1.zip"),
			},
			{
				Root:    string(id11),
				ZipFile: "/no/such/directory/" + uuid.NewString() + "/test1.zip",
			},
			{
				Root:    string(id11),
				TarFile: "/no/such/directory/" + uuid.NewString() + "/test1.tar",
			},
		}

		for _, req := range requests {
			_, err := serverapi.Restore(ctx, cli, req)

			var se apiclient.HTTPStatusError

			require.ErrorAs(t, err, &se)
		}
	})
}

